import sys

mod = 998244353

def pow_mod(a, b):
    res = 1
    while b > 0:
        if b % 2 == 1:
            res = (res * a) % mod
        a = (a * a) % mod
        b //= 2
    return res

class Matrix:
    def __init__(self, a=None, b=None, c=None, d=None, mat=None):
        if mat is not None:
            self.mat = [row[:] for row in mat]
        else:
            self.mat = [[a, b], [c, d]]

    def pow(self, x):
        res = Matrix(1, 0, 0, 1)
        a = Matrix(mat=self.mat)
        while x > 0:
            if x % 2 == 1:
                res = res.mult(a)
            a = a.mult(a)
            x //= 2
        return res

    def mult(self, m):
        rmat = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    rmat[i][j] += self.mat[i][k] * m.mat[k][j]
                rmat[i][j] %= mod
        return Matrix(mat=rmat)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    L = int(input_data[2])
    R = int(input_data[3])

    total = (R - L + 1) % mod

    if n % 2 == 1 and m % 2 == 1:
        print(pow_mod(total, n * m))
    else:
        if total % 2 == 0:
            allbutone = pow_mod(total, n * m - 1)
            res = (allbutone * (total // 2)) % mod
            print(res)
        else:
            k = total // 2
            id_matrix = Matrix(1, 0, 0, 1)
            mat = Matrix(k, k + 1, k + 1, k)
            res = mat.pow(n * m)
            print(res.mat[0][0])

if __name__ == "__main__":
    main()

